// browseAriaDoc is the Ария series document: the shikimori namespace wins the
// walk (the serial module's only modeled title source) with the RU pick, and
// carries the synopsis facts — description first (the carrier test), genres/
// kind/status riding along (the D8 whole-winner law).
const browseAriaDoc = `{"sources": {"shikimori": {
	"title": {"russian": "Ария", "romaji": "Aria"},
	"description": "Пилоты на воде",
	"genres": ["Action", "Sci-Fi"],
	"kind": "tv",
	"status": "Ongoing"
}}}`

// browsePutSeries persists one series row and returns its minted id (the
// store's seriesID formula owns the identity — tests read it back, never
// re-derive it).
func browsePutSeries(t *testing.T, st *store.Store, ctx context.Context, libraryID int64, path, status string) string {
	t.Helper()
	if err := st.PutSeries(ctx, store.Series{
		ModuleID: "serial", LibraryID: libraryID, RelativePath: path,
		Status:   status,
		Document: []byte(browseAriaDoc),
	}); err != nil {
		t.Fatalf("PutSeries %s: %v", path, err)
	}
	sr, err := st.GetSeriesByPath(ctx, libraryID, path, access.System())
	if err != nil {
		t.Fatalf("GetSeriesByPath %s: %v", path, err)
	}
	return sr.ID
}

// TestBrowseCorpusComposesAndSearches drives the boot-build joint over real
// instances: the composed name is the match tier («Ария» through the fold),
// the unpicked romaji alternate recalls "aria", the episode composes its
// element name against the series, photo libraries stay out of the corpus
// (OQ1), a tombstoned row indexes nowhere, and the facet aggregates count
// exactly what the About resolver resolves.
func TestBrowseCorpusComposesAndSearches(t *testing.T) {
	st, _, ctx, w, svc := browseFixture(t)

	serials, err := st.CreateLibrary(ctx, "serial", "/data/serials", "Serials")
	if err != nil {
		t.Fatalf("CreateLibrary serials: %v", err)
	}
	aria := browsePutSeries(t, st, ctx, serials, "Ария", "")
	if err := st.PutItem(ctx, store.Item{
		ID: "it_ep", ModuleID: "serial", LibraryID: serials, FileID: "f_ep",
		RelativePath: "Ария/ep.mkv",
		Document:     []byte(`{"parsed": {"series_relative_path": "Ария"}, "sources": {"serial-parser": {"season": 1, "episode": 2}}}`),
	}); err != nil {
		t.Fatalf("PutItem episode: %v", err)
	}
	// A photo library: the image module's media type keeps it out of the
	// corpus (OQ1) — its row still counts in the epoch's corpus leg.
	photos, err := st.CreateLibrary(ctx, "image", "/data/photos", "Photos")
	if err != nil {
		t.Fatalf("CreateLibrary photos: %v", err)
	}
	if err := st.PutItem(ctx, store.Item{
		ID: "it_img", ModuleID: "image", LibraryID: photos, FileID: "f_img",
		RelativePath: "DSC_0001.jpg",
		Document:     []byte(`{"sources": {"image-enricher": {"title": "Кадр первый"}}}`),
	}); err != nil {
		t.Fatalf("PutItem photo: %v", err)
	}
	// A tombstoned series row: status deleted — never indexed, never counted.
	browsePutSeries(t, st, ctx, serials, "Томбстоун", "deleted")

	svc.Build()

	// The composed name matches through the fold, case and ё/е included.
	if hits := svc.Search("ариЯ"); !browseHasID(hits.Series, aria) {
		t.Fatalf("Search(ариЯ) series = %v, want %q through the fold", hits.Series, aria)
	}
	// The unpicked romaji is the alternate tier — "aria" must still hit.
	if hits := svc.Search("aria"); !browseHasID(hits.Series, aria) {
		t.Fatalf("Search(aria) series = %v, want %q through the romaji alternate", hits.Series, aria)
	}
	// The episode composes "Ария · S01E02" (the serial module's element
	// template) and matches under it.
	if hits := svc.Search("Ария · S01E02"); !browseHasID(hits.Items, "it_ep") {
		t.Fatalf("Search(Ария · S01E02) items = %v, want the composed episode", hits.Items)
	}
	// Photos are excluded by the corpus — the enriched title matches nothing.
	if hits := svc.Search("Кадр первый"); len(hits.Items) != 0 || len(hits.Series) != 0 {
		t.Fatalf("Search(Кадр первый) = %v, want empty (photo library excluded, OQ1)", hits)
	}
	// The live set is exactly the two live media rows — the tombstone and
	// the photo row absent — the orphan sweep's input.
	live := w.Deps.LiveIDs()
	if len(live) != 2 || !live[aria] || !live["it_ep"] {
		t.Fatalf("LiveIDs = %v, want {%q, it_ep} — tombstone and photo out", live, aria)
	}
	// Facet counts equal what the About resolver resolves: one carrier series
	// → Action=1, Sci-Fi=1, kind=tv=1; the photo library serves no facets.
	for _, f := range svc.Facets(strconv.FormatInt(serials, 10)) {
		switch f.Key {
		case "genres":
			if len(f.Values) != 2 {
				t.Fatalf("genres values = %v, want Action and Sci-Fi once each", f.Values)
			}
		case "kind":
			if len(f.Values) != 1 || f.Values[0].Value != "tv" || f.Values[0].Count != 1 {
				t.Fatalf("kind values = %v, want tv=1", f.Values)
			}
		case "status":
			if len(f.Values) != 1 || f.Values[0].Value != "Ongoing" {
				t.Fatalf("status values = %v, want Ongoing=1", f.Values)
			}
		default:
			t.Fatalf("unexpected facet key %q", f.Key)
		}
	}
	if fs := svc.Facets(strconv.FormatInt(photos, 10)); len(fs) != 0 {
		t.Fatalf("Facets(photos) = %v, want empty (photo library, honest absence)", fs)
	}
	// The facet-filter id sets resolve against the SAME corpus: genre/kind hit
	// the carrier series only; an unknown value is the empty set (the
	// unknown-value law); the episode document carries no about.
	sids, iids, err := w.FacetIDs(ctx, serials, "Action", "", "")
	if err != nil {
		t.Fatalf("FacetIDs(Action): %v", err)
	}
	if !sids[aria] || len(sids) != 1 || len(iids) != 0 {
		t.Fatalf("FacetIDs(Action) = %v / %v, want {%q} / {}", sids, iids, aria)
	}
	if sids, _, err = w.FacetIDs(ctx, serials, "NoSuch", "", ""); err != nil {
		t.Fatalf("FacetIDs(NoSuch): %v", err)
	}
	if len(sids) != 0 {
		t.Fatalf("FacetIDs(NoSuch) = %v, want the empty set (200 empty)", sids)
	}
	if _, iids, err = w.FacetIDs(ctx, serials, "", "tv", ""); err != nil {
		t.Fatalf("FacetIDs(kind=tv): %v", err)
	}
	if len(iids) != 0 {
		t.Fatalf("FacetIDs(kind=tv) items = %v, want empty (episode docs carry no about)", iids)
	}
}

// TestBrowseEpochTripsOnConfigWrites pins the two-part scalar epoch over the
// real control tables: the corpus-count leg counts items+series across ALL
// libraries (photos included — an add or a delete must converge), the
// naming-config horizon moves on a title override and on a gate pref write,
// and content-row updates move NEITHER leg (their convergence is the
// watermark walk, not drift).
func TestBrowseEpochTripsOnConfigWrites(t *testing.T) {
	st, _, ctx, w, _ := browseFixture(t)

	serials, err := st.CreateLibrary(ctx, "serial", "/data/serials", "Serials")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	aria := browsePutSeries(t, st, ctx, serials, "Ария", "")
	e := w.Deps.Epoch()
	if e.Rows != 1 || e.UpdatedAt == "" {
		t.Fatalf("epoch after seed = %+v, want Rows=1 and a non-empty stamp", e)
	}

	// A content-row update moves nothing — the watermark walk's input.
	browsePutSeries(t, st, ctx, serials, "Ария", "")
	if now := w.Deps.Epoch(); now != e {
		t.Fatalf("epoch after content rewrite = %+v, want unchanged %+v", now, e)
	}

	// A corpus add trips the count leg.
	if err := st.PutItem(ctx, store.Item{
		ID: "it_ep", ModuleID: "serial", LibraryID: serials, FileID: "f_ep",
		Document: []byte(`{"sources": {"serial-parser": {"season": 1, "episode": 2}}}`),
	}); err != nil {
		t.Fatalf("PutItem: %v", err)
	}
	if now := w.Deps.Epoch(); now.Rows != 2 {
		t.Fatalf("epoch Rows after add = %d, want 2", now.Rows)
	}

	// A title override (the naming horizon's own table) trips the stamp leg.
	if _, err := st.SetTitleOverride(ctx, aria, "Новое имя"); err != nil {
		t.Fatalf("SetTitleOverride: %v", err)
	}
	if now := w.Deps.Epoch(); now == e {
		t.Fatal("epoch after title override unchanged, want the stamp leg moved")
	}

	// A source-gate pref write moves the horizon too.
	if err := st.UpsertMetadataSourcePref(ctx, store.MetadataSourcePref{
		ModuleID: "serial", LibraryID: serials, PluginID: "shikimori", Enabled: false,
	}); err != nil {
		t.Fatalf("UpsertMetadataSourcePref: %v", err)
	}
	if now := w.Deps.Epoch(); now.UpdatedAt == e.UpdatedAt {
		t.Fatal("epoch stamp unchanged after pref write, want it moved")
	}

	// A delete trips the count leg — Q3: no timestamp bump needed.
	if err := st.DeleteLibrary(ctx, serials); err != nil {
		t.Fatalf("DeleteLibrary: %v", err)
	}
	if now := w.Deps.Epoch(); now.Rows != 0 {
		t.Fatalf("epoch Rows after delete = %d, want 0", now.Rows)
	}
}

// TestBrowseChangedWalksWatermark pins the incremental path over real rows:
// the full-scan walk returns exactly the rows whose updated_at passed the
// watermark and advances the stamp; a corrupt watermark (never a production
// state) advances nothing.
func TestBrowseChangedWalksWatermark(t *testing.T) {
	st, _, ctx, w, _ := browseFixture(t)

	serials, err := st.CreateLibrary(ctx, "serial", "/data/serials", "Serials")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	aria := browsePutSeries(t, st, ctx, serials, "Ария", "")

	entries, docs, watermark := w.Deps.Corpus()
	if len(entries) != 1 || entries[0].ID != aria {
		t.Fatalf("Corpus entries = %v, want exactly %q", entries, aria)
	}
	if len(docs[strconv.FormatInt(serials, 10)]) == 0 {
		t.Fatalf("Corpus facet docs for lib %d = %v, want the series document", serials, docs)
	}
	if watermark == "" {
		t.Fatal("Corpus watermark = empty, want the row's updated_at stamp")
	}

	// Idle: nothing moved, the walk returns nothing and holds the stamp.
	if got, wm := w.Deps.Changed(watermark); len(got) != 0 || wm != watermark {
		t.Fatalf("idle Changed = %d entries, watermark %q; want none and %q", len(got), wm, watermark)
	}

	// A new row joins the walk's answer with the stamp advanced.
	strela := browsePutSeries(t, st, ctx, serials, "Стрела", "")
	got, next := w.Deps.Changed(watermark)
	if len(got) != 1 || got[0].ID != strela {
		t.Fatalf("Changed = %v, want exactly the new series %q", got, strela)
	}
	if next == "" || next == watermark {
		t.Fatalf("Changed watermark = %q, want advanced past %q", next, watermark)
	}

	// An unparseable watermark advances nothing and walks nothing.
	if got, wm := w.Deps.Changed("not-a-stamp"); len(got) != 0 || wm != "not-a-stamp" {
		t.Fatalf("corrupt-watermark Changed = %d entries, watermark %q; want none, held", len(got), wm)
	}
}

// TestBrowseJanitorTaskBootWarmAndWake pins the task shape from the
// composition root's parts: the boot-run warms the never-built service
// synchronously (search answers before any tick), the interval is the locked
// 60 s rule constant (OQ4), and the wake channel — the one the scan-complete
// and gate-flip fan-outs and OnTitleChange poke — runs a reconcile pass at
// once, so a row added after boot is searchable without waiting out the
// interval.
func TestBrowseJanitorTaskBootWarmAndWake(t *testing.T) {
	st, _, ctx, _, svc := browseFixture(t)

	serials, err := st.CreateLibrary(ctx, "serial", "/data/serials", "Serials")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	aria := browsePutSeries(t, st, ctx, serials, "Ария", "")

	// The task main() registers: the browse interval, the service's wake
	// channel as the wake, Reconcile as the body (the never-built reconcile
	// floors to the boot build).
	if browseInterval != 60*time.Second {
		t.Fatalf("browseInterval = %v, want the locked 60 s tick (OQ4)", browseInterval)
	}
	j := newJanitor(janitorTask{
		name:     "browse",
		interval: browseInterval,
		wake:     svc.WakeChan(),
		fn:       func(context.Context) { svc.Reconcile() },
	})
	j.runBoot(ctx)
	if hits := svc.Search("ариЯ"); !browseHasID(hits.Series, aria) {
		t.Fatalf("post-boot Search = %v, want the boot-warm to have built the index", hits.Series)
	}

	// The tick loop starts after the boot (main's jan.run) — the wake's
	// consumer.
	ctx2, cancel := context.WithCancel(context.Background())
	defer cancel()
	done := make(chan struct{})
	go func() {
		defer close(done)
		j.run(ctx2)
	}()

	// A post-boot row surfaces through the poke, not the tick.
	strela := browsePutSeries(t, st, ctx, serials, "Стрела", "")
	svc.Wake()
	deadline := time.Now().Add(2 * time.Second)
	for {
		if hits := svc.Search("Стрела"); browseHasID(hits.Series, strela) {
			break
		}
		if time.Now().After(deadline) {
			t.Fatal("wake: the new series never surfaced within 2s of the poke")
		}
		time.Sleep(time.Millisecond)
	}
	cancel()
	<-done
}

// TestBrowseNamerCacheReconverges pins the namer cache's per-pass invariant
// (the 4.1 clause-6 surface): the boot build caches the library's namer, a
// source-gate flip trips the epoch, and exactly ONE Reconcile — the drift
// rebuild — must drop the flipped source's facet aggregates whole, resolving
// through a FRESH namer rather than the stale cached one (without the
// per-pass clear the aggregate kept counting under pre-flip gates until
// restart). A second Reconcile converges identically — no oscillation.
func TestBrowseNamerCacheReconverges(t *testing.T) {
	st, _, ctx, w, svc := browseFixture(t)

	serials, err := st.CreateLibrary(ctx, "serial", "/data/serials", "Serials")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	aria := browsePutSeries(t, st, ctx, serials, "Ария", "")
	libID := strconv.FormatInt(serials, 10)

	// The build: facets count the shikimori carrier, and FacetIDs resolves
	// through the same cached namer — the cache is warm under the pre-flip
	// gates from here on.
	svc.Build()
	fs := svc.Facets(libID)
	carries := false
	for _, f := range fs {
		if f.Key != "genres" {
			continue
		}
		for _, v := range f.Values {
			if v.Value == "Action" && v.Count == 1 {
				carries = true
			}
		}
	}
	if !carries {
		t.Fatalf("pre-flip facets = %v, want genres Action=1 (the shikimori carrier)", fs)
	}
	sids, _, err := w.FacetIDs(ctx, serials, "Action", "", "")
	if err != nil {
		t.Fatalf("pre-flip FacetIDs(Action): %v", err)
	}
	if !sids[aria] || len(sids) != 1 {
		t.Fatalf("pre-flip FacetIDs(Action) = %v, want {%q}", sids, aria)
	}

	// The gate flip: the serial module's only modeled title source disabled —
	// the resolver's chain loses its carrier, so the facets must drop WHOLE
	// on the drift rebuild the flip's epoch trip forces.
	if err := st.UpsertMetadataSourcePref(ctx, store.MetadataSourcePref{
		ModuleID: "serial", LibraryID: serials, PluginID: "shikimori", Enabled: false,
	}); err != nil {
		t.Fatalf("UpsertMetadataSourcePref: %v", err)
	}

	// Exactly one Reconcile: the epoch drift trips the full rebuild, whose
	// walk clears the cache — the aggregates and the id sets resolve fresh.
	svc.Reconcile()
	dropped := func(stage string) {
		t.Helper()
		if fs := svc.Facets(libID); len(fs) != 0 {
			t.Fatalf("%s: facets = %v, want dropped whole (shikimori gate off)", stage, fs)
		}
		sids, _, err := w.FacetIDs(ctx, serials, "Action", "", "")
		if err != nil {
			t.Fatalf("%s: FacetIDs(Action): %v", stage, err)
		}
		if len(sids) != 0 {
			t.Fatalf("%s: FacetIDs(Action) = %v, want the empty set (gate off)", stage, sids)
		}
	}
	dropped("post-flip")

	// A second Reconcile converges identically — the epoch held, the idle
	// pass recomputes nothing, the model does not oscillate.
	svc.Reconcile()
	dropped("second pass")
}

// browseHasID reports whether ids carries id — the hit-list assertion helper.
func browseHasID(ids []string, id string) bool {
	for _, got := range ids {
		if got == id {
			return true
		}
	}
	return false
}
